const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "sqlite",
  "inlineSchema": "// ═══════════════════════════════════════════════════════════════\n// P0-5 · Bot 可选模块 schema（2026-09-28 从核心 schema 移出）\n//\n// 本文件与 core.prisma 一起参与 prisma generate（同一 client、同一次生成），\n// 因此**业务代码零改动**。它的意义：\n//   · 多租户 / 开源核心改造只面对 core.prisma，6 张 Bot 表 + 4 个 Bot 枚举\n//     不再进入改造面（原估可减少约 14% 多租户改造量）\n//   · 开源发行构建可在打包时排除本文件（配合「默认关闭的可选模块」定位，\n//     见 docs/OPEN-CORE-POSITIONING.md §4；届时需同时移除 Bot 代码路径）\n//\n// 注意：User.isBot / botType / botConfig 是 User 表的列（核心侧），\n// 属数据列而非表，本阶段不迁移 —— 迁移它们需要破坏性 DB 变更。\n// ═══════════════════════════════════════════════════════════════\n\n// ═══════════════════════════════════════════════════════════════\n// BOT SYSTEM — Digital User Models\n// ═══════════════════════════════════════════════════════════════\n\nenum BotType {\n  SEED // 种子用户，冷启动用\n  SIMULATION // 行为模拟用户\n  TRAINING // 训练数据生成\n  ACTIVE // 活跃参与匹配\n}\n\nenum BotActivityLevel {\n  GHOST // 隐身，仅匹配不可见\n  LOW // 低活跃度 (10% 在线时间)\n  MEDIUM // 中活跃度 (30% 在线时间)\n  HIGH // 高活跃度 (60% 在线时间)\n  FULL // 全天候在线\n}\n\nenum Ethnicity {\n  CAUCASIAN\n  AFRICAN_AMERICAN\n  HISPANIC_LATINO\n  ASIAN\n  SOUTH_ASIAN\n  MIDDLE_EASTERN\n  MIXED\n  OTHER\n}\n\nenum OnlinePattern {\n  MORNING // 6AM-12PM\n  AFTERNOON // 12PM-6PM\n  EVENING // 6PM-12AM\n  NIGHT // 12AM-6AM\n  RANDOM\n  WORK_HOURS // 9AM-5PM\n  AFTER_WORK // 5PM-10PM\n}\n\n// Bot扩展资料 - 数字用户详细信息\nmodel BotProfile {\n  id        String @id @default(cuid())\n  // P0-5 拆分说明：与核心 Profile 的关联降级为普通列（DB 侧 FK 保留不变）。\n  // 跨文件 Prisma 关系要求 core.prisma 声明反向字段（P1012），会让核心 schema\n  // 重新引用 Bot 类型 —— 违背本拆分的目的。查询路径：先按 userId 查 Profile.id，\n  // 再按 profileId 查本表（见 src/lib/bot-automation.ts 的 findBotProfileByUserId）。\n  profileId String @unique\n\n  // 基础配置\n  botType       BotType          @default(SEED)\n  activityLevel BotActivityLevel @default(LOW)\n\n  // 人口统计扩展\n  ethnicity      Ethnicity?\n  occupation     String? // \"Software Engineer\", \"Teacher\", etc.\n  industry       String? // \"Tech\", \"Healthcare\", \"Finance\", etc.\n  educationLevel String? // \"High School\", \"Bachelor's\", \"Master's\", \"PhD\"\n  incomeRange    String? // \"$30k-50k\", \"$50k-100k\", etc.\n\n  // 兴趣与偏好 (JSON arrays - SQLite compatible)\n  interests   String @default(\"[]\") // JSON: [\"hiking\", \"cooking\", \"photography\"]\n  hobbies     String @default(\"[]\") // JSON: [\"gaming\", \"yoga\", \"reading\"]\n  musicGenres String @default(\"[]\") // JSON: [\"rock\", \"jazz\", \"electronic\"]\n  movieGenres String @default(\"[]\") // JSON: [\"thriller\", \"romance\", \"sci-fi\"]\n\n  // 行为模拟配置\n  onlinePattern   OnlinePattern @default(EVENING)\n  avgResponseTime Int           @default(30) // 平均响应时间（分钟）\n  maxDailyMatches Int           @default(3) // 每日最大匹配数\n\n  // 行为概率配置（JSON）\n  behaviorConfig String?\n\n  // 匹配偏好（扩展 Profile 的 preferred* 字段）(JSON arrays)\n  preferredEthnicities String @default(\"[]\") // JSON: Ethnicity[]\n  preferredOccupations String @default(\"[]\") // JSON: string[]\n  preferredEducation   String @default(\"[]\") // JSON: string[]\n\n  // 学习状态\n  totalInteractions  Int   @default(0)\n  successfulMatches  Int   @default(0)\n  avgEngagementScore Float @default(0) // 0-100\n\n  // 学习数据（JSON）\n  learningData String?\n\n  // 头像配置\n  avatarStyle  String? // \"professional\", \"casual\", \"artistic\"\n  avatarSource String? // \"generated\", \"stock\", \"ai_avatar\"\n\n  // 状态\n  isActive     Boolean   @default(true)\n  lastActiveAt DateTime?\n  sleepUntil   DateTime? // 暂停到指定时间\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([botType])\n  @@index([activityLevel])\n  @@index([isActive])\n}\n\n// Bot行为交互日志\nmodel BotInteractionLog {\n  id           String  @id @default(cuid())\n  botUserId    String\n  targetUserId String?\n  matchId      String?\n\n  // 交互类型\n  interactionType String // \"match_received\", \"match_reacted\", \"message_sent\", \"message_received\", \"profile_viewed\"\n\n  // 行为详情\n  action        String // \"accept\", \"pass\", \"respond\", \"initiate\"\n  responseDelay Int? // 响应延迟（秒）\n\n  // 结果\n  outcome         String? // \"success\", \"rejected\", \"no_response\", \"blocked\"\n  engagementScore Int? // 0-100 参与度评分\n\n  // 上下文\n  context String? // JSON: {matchScore, matchReason, etc.}\n\n  createdAt DateTime @default(now())\n\n  @@index([botUserId, createdAt])\n  @@index([interactionType])\n  @@index([outcome])\n}\n\n// Bot学习批次\nmodel BotLearningBatch {\n  id String @id @default(cuid())\n\n  // 批次信息\n  batchNumber Int\n  status      String @default(\"pending\") // pending, running, completed, failed\n\n  // 数据范围\n  startDate DateTime\n  endDate   DateTime\n\n  // 统计数据\n  totalInteractions Int   @default(0)\n  avgEngagement     Float @default(0)\n  successRate       Float @default(0)\n\n  // 更新的偏好配置\n  preferenceUpdates String? // JSON array of changes\n\n  // 执行日志\n  executionLog String?\n\n  createdAt   DateTime  @default(now())\n  completedAt DateTime?\n\n  @@index([status])\n  @@index([batchNumber])\n}\n\n// Bot学习记录 - 实时交互数据\nmodel BotLearningRecord {\n  id     String @id @default(cuid())\n  botId  String\n  userId String // 交互对象用户ID\n\n  // 交互类型\n  interactionType String // MATCH_REQUEST, MATCH_ACCEPT, CHAT_MESSAGE, etc.\n  outcome         String // POSITIVE, NEUTRAL, NEGATIVE\n\n  // 上下文数据\n  context String? // JSON string (SQLite compatible)\n\n  // 处理状态\n  processed Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([botId])\n  @@index([processed])\n  @@index([createdAt])\n  @@index([interactionType])\n}\n\n// Bot偏好向量 - 学习结果\nmodel BotPreference {\n  id    String @id @default(cuid())\n  botId String @unique\n\n  // 五维偏好 (0-1)\n  relationshipStructure Float @default(0.5)\n  communicationStyle    Float @default(0.5)\n  interests             Float @default(0.5)\n  values                Float @default(0.5)\n  lifestyle             Float @default(0.5)\n\n  // 元数据\n  confidence Float @default(0.1) // 置信度 (0-1)\n  sampleSize Int   @default(0) // 样本数量\n\n  createdAt   DateTime @default(now())\n  lastUpdated DateTime @updatedAt\n\n  @@index([botId])\n}\n\n// Bot头像管理\nmodel BotAvatar {\n  id           String  @id @default(cuid())\n  botId        String  @unique\n  originalUrl  String?\n  processedUrl String? // 处理后（压缩、优化）的URL\n\n  style     String // 原始风格\n  ethnicity String // 原始种族标签\n\n  status   String @default(\"pending\") // pending, active, failed, retired\n  useCount Int    @default(0) // 使用次数\n\n  generatedAt DateTime  @default(now())\n  lastUsedAt  DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ═══════════════════════════════════════════════════════════════\n// CONNECTION OS — 业务闭环实体（自 T02 起逐任务追加）\n//\n// 对齐契约：\n//   - contracts/schema.sql:15-20   (missions)\n//   - contracts/connection.openapi.yaml  /missions 与 /v1/missions/{missionId}\n//\n// 设计约束（继承 T01 的 tenancy.prisma，见 docs/implementation/T01/DIALECT-DIFF.md）：\n//   1. **方言无关**：本文件不出现任何 `@db.*` 原生类型标注。同一份定义可同时为\n//      libSQL（当前生产）与 PostgreSQL（M6 目标）生成；差异只体现在迁移 SQL。\n//   2. **复合语义字段走 `String` + 单点 codec**：libSQL 无 `jsonb`，契约里的\n//      `jsonb` 一律落为 JSON 文本，编解码**只允许**经 `src/lib/connection/json-codec.ts`。\n//      散落的 `JSON.parse` 会导致「有的存字符串、有的存对象」的静默腐化。\n//   3. **`organizationId` 一律由服务端从会话派生**（`resolveTenant()`），\n//      绝不接受客户端传入值作为授权依据。\n//   4. **加列优先 / 只增不改**：新任务只往本文件加模型；改动既有列语义需走 MIGRATION_PLAN。\n// ═══════════════════════════════════════════════════════════════\n\n/// Mission 生命周期。契约 missions.status 为自由 text（默认 'draft'），\n/// 这里收敛为枚举 —— 取值与 `src/lib/connection/missions.ts` 的状态机逐字一致。\nenum MissionStatus {\n  DRAFT // 草稿：不可分享，分享链接返回 404\n  ACTIVE // 已发布：分享页可访问，可被加入\n  PAUSED // 已暂停：分享页只读，拒绝新加入（保留历史）\n  CLOSED // 已关闭：分享页只读，终止\n}\n\n/// 成员加入 Mission 的状态。\n/// ⚠️ 与 T03 的 `SocialIntent` 分工：本模型只表达「谁加入了哪个任务」（粗粒度、必填），\n/// `SocialIntent` 表达「该成员的 need/offer/逐字段披露范围」（细粒度，T03 交付）。\n/// 二者是 1:1 互补关系，不是重复建模。\nenum MissionParticipationStatus {\n  INTERESTED // 已加入/表达参与意愿\n  WITHDRAWN // 本人撤销\n  REMOVED // 运营移出\n}\n\n/// 连接任务。对应契约 missions 表。\nmodel Mission {\n  id             String @id @default(cuid())\n  /// 租户归属。**必填**（T01 起新表直接带上，不再走加列批次）。\n  organizationId String\n  /// 任务发起人。契约 persons 同义于本仓 `User`。\n  ownerId        String\n\n  title           String\n  goal            String\n  offer           String\n  /// 约束（JSON 文本，字符串数组）。**必须**经 json-codec 读写。\n  constraints     String?\n  /// 成功标准：验收「连接是否达成」的判据（PRD 要求可判定，非口号）。\n  successCriteria String\n\n  status MissionStatus @default(DRAFT)\n\n  /// 分享令牌：`/m/<shareToken>` 的唯一寻址方式。\n  /// 高熵、不可枚举、URL-safe；**即能力凭证**，故不可预测、不可自增。\n  shareToken    String  @unique\n  /// 是否允许**未注册**访客预览（最小披露）。关闭后分享页一律要求登录。\n  publicPreview Boolean @default(true)\n\n  /// 限额。null = 不限。\n  maxParticipants Int?\n\n  expiresAt   DateTime? // 截止（过期后分享页只读、拒绝新加入）\n  publishedAt DateTime? // 首次 publish 时间\n  closedAt    DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  organization   Organization           @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  owner          User                   @relation(\"UserMissions\", fields: [ownerId], references: [id], onDelete: Cascade)\n  participations MissionParticipation[]\n\n  @@index([organizationId, status])\n  @@index([organizationId, createdAt])\n  @@index([expiresAt])\n}\n\n/// 成员 × Mission 的加入关系。契约中没有独立表（契约把 memberships 与\n/// social_intents 直接挂 organization），这里显式建模是为了：\n///   1. 让「加入」可计数、可撤销、可审计（AC-11 的加入动作需要落库）；\n///   2. 给 T03 的 `SocialIntent` 一个稳定的父锚点（`missionId` + `userId`）。\nmodel MissionParticipation {\n  id             String                     @id @default(cuid())\n  organizationId String\n  missionId      String\n  userId         String\n  status         MissionParticipationStatus @default(INTERESTED)\n  /// 加入时的可选留言（最小披露：不进入公开投影）。\n  note           String?\n  createdAt      DateTime                   @default(now())\n  updatedAt      DateTime                   @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  mission      Mission      @relation(fields: [missionId], references: [id], onDelete: Cascade)\n  user         User         @relation(\"UserMissionParticipations\", fields: [userId], references: [id], onDelete: Cascade)\n\n  /// 同一任务同一成员只能有一条加入记录（幂等 join 的落点）。\n  @@unique([missionId, userId])\n  @@index([organizationId, status])\n  @@index([userId, status])\n}\n\n/// 幂等记录。契约对 `POST /missions` 强制要求 `Idempotency-Key` 请求头\n/// （connection.openapi.yaml:12-19）。同样的键重复提交必须返回**首次结果**，\n/// 不得创建第二条 Mission —— 这是 AC-07（幂等）在本任务的最小落点。\n///\n/// 键空间是 `(organizationId, scope, key)`：同一把 key 在不同租户/不同业务动作下\n/// 互不干扰，避免跨租户串号。\nmodel IdempotencyRecord {\n  id             String   @id @default(cuid())\n  organizationId String\n  /// 业务动作，如 `mission.create` / `mission.join`。\n  scope          String\n  /// 客户端提交的 Idempotency-Key 原文。\n  key            String\n  /// 请求体指纹（sha256）。同一 key 配不同请求体 → 409（防止「键复用了但意图变了」）。\n  requestHash    String\n  resourceType   String\n  resourceId     String?\n  createdAt      DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@unique([organizationId, scope, key])\n  @@index([organizationId, createdAt])\n}\n\n// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../src/generated\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// ═══════════════════════════════════════════════════════════════\n// AUTH — NextAuth v5 compatible models\n// ═══════════════════════════════════════════════════════════════\n\nmodel User {\n  id            String    @id @default(cuid())\n  name          String?\n  email         String    @unique\n  emailVerified DateTime?\n  image         String?\n\n  // Auth\n  password     String?\n  role         UserRole  @default(USER)\n  tokenVersion Int       @default(0) // bumped on password change/reset to invalidate all previously-issued JWT sessions\n  accounts     Account[]\n  sessions     Session[]\n\n  // Bot/Digital User Flags\n  isBot     Boolean @default(false) // 标记是否为数字用户\n  botType   String? // \"simulation\" | \"training\" | \"seed\"\n  botConfig String? // 数字用户行为配置（JSON字符串存储）\n\n  // Email Verification\n  verificationTokens VerificationToken[] @relation(\"UserVerificationTokens\")\n\n  // Profile\n  profile Profile?\n\n  // Matching\n  sentMatches     Match[]         @relation(\"SentMatches\")\n  receivedMatches Match[]         @relation(\"ReceivedMatches\")\n  matchReactions  MatchReaction[]\n\n  // Chat\n  // P1-6 阶段 5：原 `chatRooms ChatRoomMember[]` / `messages Message[]` 关系\n  // 随 Legacy 三表删除而移除。\n\n  // IM Module\n  conversationsA      Conversation[]            @relation(\"ConversationUserA\")\n  conversationsB      Conversation[]            @relation(\"ConversationUserB\")\n  imMessages          IMMessage[]               @relation(\"IMMessageSender\")\n  messageReceipts     MessageReceipt[]\n  messageReactions    MessageReaction[]\n  imParticipants      ConversationParticipant[]\n  presence            UserPresence?\n  powerBoardRule      PowerBoardRule?\n  consentRequestsMade ConsentRequest[]          @relation(\"ConsentRequester\")\n  consentRequestsRecv ConsentRequest[]          @relation(\"ConsentTarget\")\n  consentGrantsMade   ConsentGrant[]            @relation(\"ConsentGranter\")\n  consentGrantsRecv   ConsentGrant[]            @relation(\"ConsentGrantee\")\n  auditLogs           AuditLog[]\n\n  // Payments\n  subscriptions Subscription[]\n  payments      Payment[]\n\n  // Notifications\n  notifications Notification[]\n\n  // Admin\n  adminAudits AdminAudit[] @relation(\"AdminAuditActor\")\n\n  // RBAC — 管理角色关联\n  adminRoles AdminUserRole[]\n\n  // T01 多租户 — 成员关系（模型定义见 prisma/schema/tenancy.prisma）\n  memberships Membership[] @relation(\"UserMemberships\")\n\n  // T02 Connection OS — Mission 发起 / 参与（模型定义见 prisma/schema/connection.prisma）\n  missions              Mission[]              @relation(\"UserMissions\")\n  missionParticipations MissionParticipation[] @relation(\"UserMissionParticipations\")\n\n  // Analytics\n  analyticsEvents AnalyticsEvent[]\n\n  // Safety & Moderation\n  reportsMade     UserReport[] @relation(\"ReportsMade\")\n  reportsReceived UserReport[] @relation(\"ReportsReceived\")\n\n  // Block List\n  blocksGiven    Block[] @relation(\"BlockerRelations\")\n  blocksReceived Block[] @relation(\"BlockedRelations\")\n\n  // Sincerity\n  sincerityWallet SincerityWallet?\n\n  // Credit Card Verification (age + identity proof, no charge)\n  cardVerified   Boolean   @default(false)\n  cardVerifiedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@index([email])\n  @@index([role])\n  @@index([createdAt])\n  @@index([deletedAt])\n  @@index([isBot]) // P1: AutoMatch bot 查找\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  id         String    @id @default(cuid())\n  identifier String // email address\n  token      String    @unique // the 6-digit code\n  expires    DateTime\n  userId     String? // optional link to user\n  user       User?     @relation(\"UserVerificationTokens\", fields: [userId], references: [id], onDelete: Cascade)\n  used       Boolean   @default(false)\n  useCount   Int       @default(0) // Track usage count for replay attack prevention\n  maxUses    Int       @default(1) // Maximum allowed uses (1 for one-time tokens)\n  lastUsedAt DateTime? // Track when token was last used\n  createdAt  DateTime  @default(now())\n\n  @@unique([identifier, token])\n  @@index([identifier])\n  @@index([userId])\n  @@index([expires])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// USER PROFILE — Relationship structure blueprint\n// ═══════════════════════════════════════════════════════════════\n\nmodel Profile {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Basic Info\n  displayName    String\n  age            Int\n  gender         Gender\n  genderIdentity String? // Free text for non-binary identification\n  sexuality      String // \"Straight\", \"Bisexual\", \"Pansexual\", \"Queer\", \"Lesbian\", \"Gay\", \"Fluid\", etc.\n  bio            String?\n  avatar         String? // Upload URL\n  avatarType     String? // \"photo\" | \"cartoon\"\n  galleryPhotos  String  @default(\"[]\") // JSON: string[] - User photo album URLs\n  city           String?\n  country        String? @default(\"US\")\n\n  // Relationship Blueprint (核心差异化数据)\n  relationshipGoal      RelationshipGoal @default(LONG_TERM)\n  attachmentStyle       String? // \"Secure\", \"Anxious-Preoccupied\", \"Dismissive-Avoidant\", \"Fearful-Avoidant\"\n  communicationStyle    String? // \"Direct\", \"Reflective\", \"Expressive\", \"Analytical\"\n  conflictResolution    String? // \"Collaborative\", \"Compromising\", \"Accommodating\", \"Competing\", \"Avoiding\"\n  loveLanguage          String? // \"Words of Affirmation\", \"Quality Time\", \"Physical Touch\", \"Acts of Service\", \"Gifts\"\n  boundaries            String? // JSON array of boundary descriptions\n  dealbreakers          String? // JSON array\n  lifePriorities        String? // JSON array: \"Career\", \"Family\", \"Adventure\", \"Stability\", etc.\n  emotionalAvailability String? // \"Fully Available\", \"Building Trust\", \"Processing Past\", \"Needs Space\"\n\n  // ═══════════════════════════════════════════════════════════════\n  // NEW: User Preference Tags for Matching (最多5个)\n  // ═══════════════════════════════════════════════════════════════\n  selectedTags String @default(\"[]\") // JSON: string[] - 用户选择的标签\n\n  // ═══════════════════════════════════════════════════════════════\n  // PHASE B: Kink & Power Dynamics Profile\n  // ═══════════════════════════════════════════════════════════════\n  domSubRole          DomSubRole? // User's primary role identity\n  preferredRole       DomSubRole? // Preferred role in a partner\n  kinkExperienceLevel KinkExperienceLevel? // Experience level in kink dynamics\n  kinkInterests       String               @default(\"[]\") // JSON: string[] - selected kink categories\n  hardLimits          String               @default(\"[]\") // JSON: string[] - absolute boundaries\n\n  // Preferences for matching\n  preferredAgeMin   Int?\n  preferredAgeMax   Int?\n  preferredGender   String?\n  preferredDistance Int? // Max distance in miles\n  preferredLocation String?\n\n  // Matching score cache (denormalized for performance)\n  compatibilityScore Int? // 0-100 overall score\n\n  // Status\n  profileStatus  ProfileStatus @default(DRAFT)\n  onboardingStep Int           @default(0) // 0-5, tracks onboarding progress\n  isApproved     Boolean       @default(false)\n  isVerified     Boolean       @default(false)\n\n  // Personality & Matching Data (for bot users)\n  personalityData String? // 完整人格数据存储（JSON字符串）\n\n  // Admin notes\n  adminNotes String?\n\n  // Bot System Relation\n\n  // ═══════════════════════════════════════════════════════════════\n  // PRODUCT OPTIMIZATION: Elite Power Features\n  // ═══════════════════════════════════════════════════════════════\n\n  // Professional Info\n  occupation        String? // Job title\n  company           String? // Company name\n  industry          String? // Industry sector\n  linkedInVerified  Boolean @default(false)\n  verificationBadge String? // \"VERIFIED\", \"ELITE\", etc.\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([gender])\n  @@index([relationshipGoal])\n  @@index([profileStatus])\n  @@index([compatibilityScore])\n  @@index([linkedInVerified])\n  @@index([gender, profileStatus])\n  @@index([isApproved])\n  @@index([attachmentStyle]) // BUG-02 FIX: Discover API 过滤加速\n  @@index([city]) // BUG-02 FIX: Discover API 城市过滤加速\n  // Discover API 加速索引\n  @@index([onboardingStep]) // P0: Discover/AutoMatch 核心过滤字段\n  @@index([age]) // P0: 年龄范围查询\n  @@index([onboardingStep, gender]) // P0: 复合过滤 (step>=N + gender=G)\n  @@index([gender, age]) // P1: 先 gender 精确匹配再 age 范围查询\n}\n\n// ═══════════════════════════════════════════════════════════════\n// MATCHING ENGINE — Core differentiation\n// ═══════════════════════════════════════════════════════════════\n\nmodel Match {\n  id String @id @default(cuid())\n\n  // Participants\n  senderId   String\n  sender     User   @relation(\"SentMatches\", fields: [senderId], references: [id])\n  receiverId String\n  receiver   User   @relation(\"ReceivedMatches\", fields: [receiverId], references: [id])\n\n  // Matching Data\n  matchScore       Float // 0-100 compatibility score\n  matchReason      String // AI-generated explanation\n  conflictWarnings String? // JSON array of potential conflicts\n\n  // Compatibility breakdown (denormalized)\n  attachmentCompat    Float? // 0-100\n  communicationCompat Float? // 0-100\n  conflictCompat      Float? // 0-100\n  valuesCompat        Float? // 0-100\n  lifestyleCompat     Float? // 0-100\n\n  // Status\n  status    MatchStatus @default(PENDING)\n  matchType MatchType   @default(WEEKLY)\n\n  // Reaction tracking\n  matchReactions MatchReaction[]\n  senderAction   MatchAction?\n  receiverAction MatchAction?\n\n  // Connection\n  // P1-6 阶段 5：原 `chatRoom ChatRoom?` 关系随 ChatRoom 表删除而移除。\n  // 会话入口改由 Conversation.matchId 反查（见 api/matches/[id]/route.ts）。\n\n  // Admin\n  reviewedBy  String?\n  reviewNotes String?\n\n  // ═══════════════════════════════════════════════════════════════\n  // PRODUCT OPTIMIZATION: Elite Power Features\n  // ═══════════════════════════════════════════════════════════════\n\n  // Pitch Message (申请信)\n  pitchMessage String? // 50-200字申请信\n  pitchTone    String? // \"casual\", \"sincere\", \"playful\", \"direct\"\n  aiAssisted   Boolean @default(false) // 是否使用AI辅助\n\n  // Sincerity Gift (诚意值附赠)\n  giftAmount Int @default(0) // 附赠诚意值数量\n\n  // Inbox Management (收件箱管理)\n  isUnread      Boolean @default(true) // 是否未读\n  inboxPriority Float? // 收件箱排序权重 (计算值)\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  expiresAt DateTime? // Auto-expire after 7 days if not acted on\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@unique([senderId, receiverId], map: \"unique_match_pair\")\n  @@index([status])\n  @@index([matchScore])\n  @@index([matchType])\n  @@index([createdAt])\n  @@index([expiresAt])\n  @@index([senderId])\n  @@index([receiverId])\n  @@index([senderId, receiverId])\n  @@index([receiverId, senderId]) // P2: OR 反向查询优化\n  @@index([isUnread])\n  @@index([inboxPriority])\n  @@index([deletedAt])\n}\n\nmodel MatchReaction {\n  id      String @id @default(cuid())\n  matchId String\n  match   Match  @relation(fields: [matchId], references: [id], onDelete: Cascade)\n  userId  String\n  user    User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  reaction MatchAction\n  feedback String? // Optional feedback on why\n\n  createdAt DateTime @default(now())\n\n  @@unique([matchId, userId])\n  @@index([userId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// P1-6 阶段 5（2026-09-28）：Legacy 三表 ChatRoom / ChatRoomMember / Message\n// 已从 schema 与数据库删除。血缘 126/126 已迁移至 IMMessage，门禁 GO。\n// 历史与执行手册：docs/CHAT-MERGE-RUNBOOK.md · docs/CHAT-MERGE-AUDIT.md\n// ═══════════════════════════════════════════════════════════════\n\n// ═══════════════════════════════════════════════════════════════\n// IM MODULE — Next-Gen Chat Infrastructure\n// ═══════════════════════════════════════════════════════════════\n\n// Conversation — logical session layer\nmodel Conversation {\n  id String @id @default(cuid())\n\n  // Participants\n  userAId     String\n  userA       User   @relation(\"ConversationUserA\", fields: [userAId], references: [id])\n  userBId     String\n  userB       User   @relation(\"ConversationUserB\", fields: [userBId], references: [id])\n  initiatorId String // who started the conversation\n\n  // Backlink to ChatRoom (migration bridge)\n  //\n  // ⚠️ 阶段 5 的 schema 编辑必须**保留 chatRoomId 标量列与唯一索引**，只删掉\n  //    `chatRoom` 关系字段（关系指向的 ChatRoom model 会被删除）。\n  //    原因：改造前 user 收藏的 /dashboard/chats/<ChatRoom.id> 旧链接里没有\n  //    Conversation.id，只能靠本列反查 —— 删掉它等于把老用户挡在\"会话不存在\"之外（G-8）。\n  //    `lib/im/resolve.ts` 的路径 2 就建立在本列的 @unique 索引上。\n  chatRoomId String? @unique\n  // P1-6 阶段 5：原 `chatRoom ChatRoom? @relation(...)` 关系随 ChatRoom 表删除而移除。\n  // 标量列 chatRoomId 与 @unique 索引**刻意保留**（G-8 旧书签别名回退，\n  // 见 lib/im/resolve.ts 路径 2）。数据库侧同步删掉了本列的外键约束。\n\n  // ═══════════════════════════════════════════════════════════════\n  // 匹配关联（G-10，阶段 5 前置修复）\n  //\n  // 发现路径：阶段 5 的 schema 清理清单原本只列了 Vault 字段。核对 `ChatRoom` 模型时\n  // 发现 `matchId` / `match.matchScore` **只存在于 ChatRoom**，而会话列表（`lib/im/list.ts`）\n  // 与会话详情都在向 UI 输出 matchScore —— 删表会让\"匹配分\"整块消失，属静默功能回退。\n  //\n  // 这里刻意**只加标量列、不加 relation**：relation 会要求 Match 侧反向声明字段，\n  // 扩大 schema 改动面；而 matchScore 只需要一次批量查询即可补齐（见 list.ts）。\n  // ═══════════════════════════════════════════════════════════════\n  matchId String?\n\n  // State\n  state       ConversationState @default(ACTIVE)\n  stateReason String? // reason for state change\n\n  // Female Control\n  controllingUserId     String? // who has control (usually female)\n  activeBoundaryVersion String? // current Power Board version\n\n  // Statistics (denormalized for performance)\n  lastMessageAt DateTime?\n  messageCount  Int       @default(0)\n  unreadCountA  Int       @default(0)\n  unreadCountB  Int       @default(0)\n\n  // Per-user settings (JSON for flexibility)\n  settings String? // JSON: { userA: {muted, pinned}, userB: {muted, pinned} }\n\n  // ═══════════════════════════════════════════════════════════════\n  // Vault —— 24h 限时对话\n  //\n  // P1-6 阶段 4（G-1 修复）：以下字段此前**只存在于 ChatRoom**。方案 A 确定 Conversation\n  // 为终局模型后，若不在删除 ChatRoom 前把它们迁移过来，阶段 5 会**整体丢失**：\n  //   · 女性用户的「终结对话」权限（vaultStatus / revokedAt / revokeReason）\n  //   · 24h 倒计时的延长审计（extensionCount / extendedAt / extendedBy）\n  //   · 截图防护的计数与取证（screenshotCount / lastScreenshotAt）\n  // 迁移脚本见 scripts/chat-merge/migrate-vault.ts（幂等 + dry-run）。\n  // ═══════════════════════════════════════════════════════════════\n\n  // Vault expiry timestamp (null = no Vault)\n  vaultExpiresAt DateTime?\n\n  // Vault 四态：ACTIVE / EXTENDED（已延长）/ REVOKED（被女性终止）/ EXPIRED（超时）\n  vaultStatus VaultStatus @default(ACTIVE)\n\n  // 延长审计\n  extensionCount Int       @default(0)\n  extendedAt     DateTime?\n  extendedBy     String?\n\n  // 女性特权：终止对话\n  revokedAt    DateTime?\n  revokedBy    String?\n  revokeReason String?\n\n  // 隐私防护\n  screenshotCount  Int       @default(0)\n  lastScreenshotAt DateTime?\n\n  // Consent cache\n  cachedConsentState ConsentState @default(CONSENT_NONE)\n\n  // Relations\n  participants    ConversationParticipant[]\n  imMessages      IMMessage[]\n  receipts        MessageReceipt[]\n  consentRequests ConsentRequest[]\n  consentGrants   ConsentGrant[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@unique([userAId, userBId], map: \"unique_conversation_pair\")\n  @@index([state])\n  @@index([lastMessageAt])\n  @@index([userAId])\n  @@index([userBId])\n  @@index([controllingUserId])\n  @@index([vaultExpiresAt])\n  // P1-6 阶段 4（G-1）：Vault 状态查询索引（与 ChatRoom 侧保持一致）\n  @@index([vaultStatus])\n  // P1-6 阶段 5（G-10）：匹配分补迁后按 matchId 反查\n  @@index([matchId])\n  @@index([deletedAt])\n}\n\n// ConversationParticipant — per-user conversation membership & state\nmodel ConversationParticipant {\n  id             String       @id @default(cuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  userId         String\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Per-user state\n  isMuted     Boolean   @default(false)\n  isPinned    Boolean   @default(false)\n  isArchived  Boolean   @default(false)\n  lastReadSeq Int       @default(0) // last read sequence number\n  lastReadAt  DateTime?\n\n  // Subscription\n  subscribedAt DateTime @default(now())\n\n  @@unique([conversationId, userId])\n  @@index([userId])\n  @@index([userId, isMuted])\n  @@index([userId, isPinned])\n}\n\n// IMMessage — next-gen message model\nmodel IMMessage {\n  id             String       @id @default(cuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  // Core fields\n  clientMsgId String? @unique // client-generated ID for dedup\n\n  // P1-6 阶段 3 迁移桥：指向被迁移的 Legacy Message.id。\n  // 幂等锚点 —— 迁移脚本以此字段判定\"已迁/未迁\"，绝不重复插入。\n  // 阶段 5（Legacy 表删除后）可安全移除本字段。\n  legacyMessageId String? @unique\n\n  senderId   String\n  sender     User   @relation(\"IMMessageSender\", fields: [senderId], references: [id])\n  receiverId String\n  seq        Int // server-assigned sequence number (monotonic per conversation)\n\n  // Content\n  msgType  IMMessageType @default(TEXT)\n  payload  String // message content (plaintext or E2EE ciphertext)\n  metadata String? // JSON: media info, links, etc.\n\n  // Encryption\n  encryptionMode     EncryptionMode @default(SERVER)\n  ephemeralPublicKey String? // for E2EE key exchange\n\n  // Boundary & compliance\n  boundaryVersion String? // current Power Board version\n  complianceTags  String           @default(\"[]\") // JSON: string[] - [\"consent_granted\", \"media_level_2\", \"pace_ok\"]\n  consentState    ConsentState     @default(CONSENT_NONE)\n  mediaLevel      MediaAccessLevel @default(L0_TEXT)\n  ruleResult      RuleEngineResult @default(PASS)\n\n  // Reply\n  replyToMsgId   String?\n  replyToPreview String? // JSON: {msgId, senderId, previewText, mediaLevel}\n\n  // Edit & Delete\n  isEdited  Boolean   @default(false)\n  editedAt  DateTime?\n  isDeleted Boolean   @default(false)\n  deletedAt DateTime?\n  deletedBy String? // who deleted (sender or admin)\n\n  // Media metadata\n  mediaMetadata String? // JSON: {mediaId, level, mimeType, sizeBytes, width, height, durationMs, thumbnailUrl, watermarkHash, isExpiring, expiresAt}\n\n  // Delivery status\n  status MessageDeliveryStatus @default(SENT)\n\n  // Receipts\n  receipts MessageReceipt[]\n\n  // Reactions\n  reactions MessageReaction[]\n\n  createdAt DateTime @default(now())\n\n  @@index([conversationId, seq])\n  @@index([conversationId, createdAt])\n  @@index([senderId])\n  @@index([receiverId])\n  @@index([clientMsgId])\n  @@index([createdAt])\n  @@index([msgType])\n  @@index([isDeleted])\n}\n\n// MessageReceipt — per-recipient delivery & read receipts\nmodel MessageReceipt {\n  id             String       @id @default(cuid())\n  messageId      String\n  message        IMMessage    @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  userId         String // who this receipt belongs to\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Receipt state\n  deliveredAt DateTime? // when message was delivered to this user\n  readAt      DateTime? // when message was read by this user\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([messageId, userId])\n  @@index([userId, readAt])\n  @@index([conversationId])\n}\n\n// MessageReaction — emoji reactions on messages\nmodel MessageReaction {\n  id        String    @id @default(cuid())\n  messageId String\n  message   IMMessage @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Emoji character\n  emoji String\n\n  createdAt DateTime @default(now())\n\n  // Each user can only add one reaction per emoji per message\n  @@unique([messageId, userId, emoji])\n  @@index([messageId])\n  @@index([userId])\n}\n\n// UserPresence — online/offline status tracking\nmodel UserPresence {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Presence state\n  status        PresenceStatus @default(OFFLINE)\n  statusMessage String? // custom status text\n  lastSeenAt    DateTime? // last heartbeat / activity timestamp\n\n  // Device info\n  deviceId   String? // current active device\n  platform   String? // \"ios\", \"android\", \"web\"\n  appVersion String? // client version\n\n  // Connection\n  connectionId String? // WebSocket connection ID\n  connectedAt  DateTime? // when current session started\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([lastSeenAt])\n  @@index([userId, status])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// CONSENT MANAGEMENT — Granular permission control\n// ═══════════════════════════════════════════════════════════════\n\nmodel ConsentRequest {\n  id             String       @id @default(cuid())\n  requesterId    String\n  requester      User         @relation(\"ConsentRequester\", fields: [requesterId], references: [id])\n  targetId       String\n  target         User         @relation(\"ConsentTarget\", fields: [targetId], references: [id])\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  // Request details\n  consentType    ConsentRequestType @default(MEDIA)\n  requestedLevel MediaAccessLevel   @default(L0_TEXT)\n  contextMsgId   String? // message that triggered this request\n  reason         String? // user-visible reason\n\n  // Preview (encrypted)\n  previewPayload String? // encrypted preview content\n\n  // State\n  state        ConsentState @default(CONSENT_PENDING)\n  respondedAt  DateTime?\n  responseNote String?\n  grantToken   String?      @unique // authorization token for verification\n\n  // Validity\n  expiresAt DateTime\n\n  createdAt DateTime @default(now())\n\n  @@index([requesterId])\n  @@index([targetId])\n  @@index([conversationId])\n  @@index([state])\n  @@index([expiresAt])\n  @@index([consentType])\n}\n\nmodel ConsentGrant {\n  id             String       @id @default(cuid())\n  granterId      String\n  granter        User         @relation(\"ConsentGranter\", fields: [granterId], references: [id])\n  granteeId      String\n  grantee        User         @relation(\"ConsentGrantee\", fields: [granteeId], references: [id])\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  // Grant details\n  consentType  ConsentRequestType @default(MEDIA)\n  grantedLevel MediaAccessLevel   @default(L0_TEXT)\n\n  // Validity\n  grantedAt DateTime  @default(now())\n  expiresAt DateTime? // null = permanent\n\n  // Revocation\n  isRevoked Boolean   @default(false)\n  revokedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([granterId])\n  @@index([granteeId])\n  @@index([conversationId])\n  @@index([consentType])\n  @@index([isRevoked])\n  @@index([expiresAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// POWER BOARD — Rule engine for boundary control\n// ═══════════════════════════════════════════════════════════════\n\nmodel PowerBoardRule {\n  id     String @id @default(cuid())\n  userId String @unique // each user has one active rule set\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Version control\n  version  String  @default(\"1.0.0\") // semantic versioning\n  isActive Boolean @default(true)\n\n  // Pace Control (JSON)\n  paceConfig String // JSON: {maxMessagesPerHour, maxMessagesPerDay, responseWindowHours, enforceCooldown, cooldownMinutes, showRemainingQuota}\n\n  // Media Policy (JSON)\n  mediaConfig String // JSON: {defaultLevel, perUserOverride, requireConsentForUpgrade, autoBlurImages, watermarkAllMedia}\n\n  // Content Filter (JSON)\n  filterConfig String // JSON: {blockedKeywords, blockedPatterns, blockExplicitImages, autoFlagProfanity, blockUnsolicitedContact, sensitivityLevel}\n\n  // Auto Response (JSON)\n  autoResponse String? // JSON: {enabled, messageTemplate, triggerAfterHours, onlyFirstMessage}\n\n  // Privacy Settings (JSON)\n  privacyConfig String // JSON: {preferredEncryption, allowScreenshotNotifications, autoExpireMessages, expireAfterDays, hideOnlineStatus, hideReadReceipts}\n\n  // Notification Preferences (JSON)\n  notifConfig String? // JSON: {pushEnabled, soundEnabled, previewEnabled, quietHoursEnabled, quietHoursStart, quietHoursEnd}\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([version])\n  @@index([isActive])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// AUDIT LOG — Immutable audit trail with hash chain\n// ═══════════════════════════════════════════════════════════════\n\nmodel AuditLog {\n  id             String  @id @default(cuid())\n  userId         String // who this log belongs to\n  user           User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  conversationId String? // related conversation\n\n  // Action details\n  action   String // \"boundary_changed\", \"consent_granted\", \"message_blocked\", \"rule_violation\", \"security_event\"\n  actorId  String? // who performed the action\n  targetId String? // who was affected\n\n  // Details (JSON - varies by action type)\n  details String? // JSON with full context\n\n  // Hash chain (tamper detection)\n  prevHash  String? // hash of previous entry\n  entryHash String // hash of this entry\n\n  // Metadata\n  ipAddress String?\n  userAgent String?\n  deviceId  String?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, createdAt])\n  @@index([conversationId])\n  @@index([action])\n  @@index([actorId])\n  @@index([createdAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// NOTIFICATIONS\n// ═══════════════════════════════════════════════════════════════\n\nmodel Notification {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  type      NotificationType\n  title     String\n  body      String\n  data      String? // JSON payload for deep links\n  actionUrl String?\n\n  isRead Boolean   @default(false)\n  readAt DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, isRead, createdAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// PAYMENTS & SUBSCRIPTIONS\n// ═══════════════════════════════════════════════════════════════\n\nmodel Subscription {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  plan   SubscriptionPlan\n  status SubscriptionStatus @default(ACTIVE)\n\n  // Stripe\n  stripeCustomerId       String?   @unique\n  stripePriceId          String?\n  stripeSubscriptionId   String?   @unique\n  stripeCurrentPeriodEnd DateTime?\n\n  // Matching perks\n  weeklyMatchLimit   Int     @default(5)\n  canInitiateChat    Boolean @default(true)\n  canViewFullProfile Boolean @default(true)\n\n  startsAt    DateTime  @default(now())\n  endsAt      DateTime?\n  cancelledAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@index([userId])\n  @@index([status])\n  @@index([deletedAt])\n  @@index([userId, status])\n}\n\nmodel Payment {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  stripePaymentIntentId String?       @unique\n  amount                Float // In USD\n  currency              String        @default(\"usd\")\n  status                PaymentStatus @default(PENDING)\n\n  description String?\n  metadata    String? // JSON\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@index([userId])\n  @@index([deletedAt])\n  @@index([createdAt, status])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// ADMIN & ANALYTICS\n// ═══════════════════════════════════════════════════════════════\n\n// 统一管理审计日志 (v3.0: 合并 AdminLog + AdminRoleAudit)\nmodel AdminAudit {\n  id String @id @default(cuid())\n\n  // 操作者\n  actorId String\n  actor   User   @relation(\"AdminAuditActor\", fields: [actorId], references: [id])\n\n  // 分类\n  category AuditCategory // \"user\" | \"match\" | \"payment\" | \"rbac\" | \"system\" | ...\n\n  // 操作\n  action String // \"create\" | \"update\" | \"delete\" | \"ban\" | \"grant_role\" | ...\n\n  // 目标对象\n  targetType String? // \"User\" | \"Match\" | \"Payment\" | \"AdminRole\" | ...\n  targetId   String? // 目标记录 ID\n\n  // 变更内容\n  changes String? // JSON: { before: {...}, after: {...} }\n  details String? // 额外上下文\n\n  // 原因（RBAC 变更等需要理由的操作）\n  reason String?\n\n  // 元数据\n  ipAddress String?\n  userAgent String?\n\n  createdAt DateTime @default(now())\n\n  @@index([actorId])\n  @@index([category, createdAt])\n  @@index([action])\n  @@index([targetType, targetId])\n  @@index([createdAt])\n}\n\n// 审计分类枚举 (v3.0)\nenum AuditCategory {\n  USER\n  MATCH\n  CHAT\n  PAYMENT\n  CONTENT\n  BOT\n  AI_CREATIVE\n  AI_SUPPORT\n  VIP\n  ANALYTICS\n  SYSTEM\n  RBAC\n}\n\nmodel AnalyticsEvent {\n  id     String  @id @default(cuid())\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  event         String // \"user.registered\", \"swipe.right\", \"message.sent\", etc.\n  eventCategory String  @default(\"\") // \"user\"|\"match\"|\"chat\"|\"revenue\"|\"admin\"\n  properties    String? // JSON with event data\n\n  sessionId  String?\n  deviceId   String  @default(\"\") // device fingerprint\n  pagePath   String  @default(\"\") // page path\n  platform   String  @default(\"web\") // web|ios|android\n  appVersion String  @default(\"\") // app version\n\n  ipAddress String?\n  country   String? // GeoIP country\n  city      String? // GeoIP city\n\n  // UTM tracking\n  utmSource   String?\n  utmMedium   String?\n  utmCampaign String?\n  utmContent  String?\n  utmTerm     String?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, event, createdAt])\n  @@index([event, createdAt])\n  @@index([eventCategory, createdAt])\n  @@index([sessionId])\n  @@index([createdAt])\n}\n\nmodel SystemConfig {\n  key         String   @id\n  value       String\n  description String?\n  updatedAt   DateTime @updatedAt\n  updatedBy   String?\n}\n\n// ═══════════════════════════════════════════════════════════════\n// RBAC — Role-Based Access Control (管理后台权限系统)\n// ═══════════════════════════════════════════════════════════════\n\n// 管理员角色枚举\nenum AdminRole {\n  SUPER_ADMIN // 超级管理员：全部权限，可管理其他管理员和角色\n  ADMIN // 管理员：用户/匹配/内容/支付全管理\n  MODERATOR // 审核员：举报审核/内容审核/用户封禁\n  ANALYST // 分析师：只读数据分析，可导出\n  SUPPORT // 客服：用户查看+基础操作，举报处理\n  CREATIVE // 创意运营：AI推广图全管理\n  VIP_AGENT // VIP客服：VIP收件箱专属\n}\n\n// 权限分类\nenum PermissionCategory {\n  USER // 用户管理\n  MATCHING // 匹配管理\n  CHAT // 聊天管理\n  PAYMENT // 支付管理\n  CONTENT // 内容审核\n  AI_CREATIVE // AI推广图\n  AI_SUPPORT // AI客服\n  VIP // VIP管理\n  ANALYTICS // 数据分析\n  SYSTEM // 系统配置\n  RBAC // 权限管理\n  BOT // Bot系统\n}\n\n// 单个权限定义\nmodel AdminPermission {\n  id          String             @id @default(cuid())\n  code        String             @unique // \"user.view\", \"user.ban\", \"payment.refund\"\n  name        String // \"查看用户\", \"封禁用户\", \"退款操作\"\n  description String?\n  category    PermissionCategory\n\n  // 元数据\n  isActive    Boolean  @default(true)\n  isDangerous Boolean  @default(false) // 高危权限（如删除/退款）需二次确认\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // 关联\n  rolePermissions AdminRolePermission[]\n\n  @@index([category])\n  @@index([isActive])\n}\n\n// 自定义角色 — 管理员可在 UI 中动态创建（v3.0+）\nmodel CustomRole {\n  id          String   @id @default(cuid())\n  name        String   @unique\n  description String?\n  isSystem    Boolean  @default(false) // 系统角色不可删除\n  permissions String // JSON数组: '[\"user.view\",\"user.ban\",...]'（SQLite不支持原生数组）\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  userRoles AdminUserRole[]\n\n  @@index([isSystem])\n}\n\n// 角色-权限关联（多对多）\nmodel AdminRolePermission {\n  id           String          @id @default(cuid())\n  role         AdminRole\n  permissionId String\n  permission   AdminPermission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  grantedAt DateTime @default(now())\n  grantedBy String? // 授权人ID\n\n  // 复合唯一约束\n  @@unique([role, permissionId])\n  @@index([role])\n}\n\n// 管理员-角色关联（多对多：一个管理员可有多个角色）\nmodel AdminUserRole {\n  id String @id @default(cuid())\n\n  // 关联到 User 表（复用现有 User 模型）\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  role AdminRole\n\n  // 自定义角色扩展（v3.0+）：可选，叠加在系统角色之上\n  customRoleId String?\n  customRole   CustomRole? @relation(fields: [customRoleId], references: [id])\n\n  // 管理员扩展信息\n  department String? // \"operations\", \"safety\", \"growth\", \"creative\", \"vip\", \"finance\"\n  title      String? // \"运营经理\", \"客服主管\"\n  isActive   Boolean @default(true)\n\n  // 时间\n  grantedAt DateTime  @default(now())\n  grantedBy String? // 授权人ID\n  expiresAt DateTime? // 过期时间（可选，用于临时权限）\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, role])\n  @@index([userId])\n  @@index([role])\n}\n\n// AdminRoleAudit 已合并到 AdminAudit (v3.0)\n\n// ═══════════════════════════════════════════════════════════════\n// ENUMS\n// ═══════════════════════════════════════════════════════════════\n\nenum UserRole {\n  USER\n  ADMIN\n  SUPER_ADMIN\n}\n\n// ═══════════════════════════════════════════════════════════════\n// PHASE B: Expanded Identity & Relationship Enums\n// ═══════════════════════════════════════════════════════════════\n\nenum Gender {\n  // Core identities\n  MAN\n  WOMAN\n  NON_BINARY\n  // Trans identities\n  TRANSGENDER_MAN\n  TRANSGENDER_WOMAN\n  // Non-binary spectrum\n  GENDERQUEER\n  GENDERFLUID\n  AGENDER\n  BIGENDER\n  PANGENDER\n  ANDROGYNE\n  DEMIGENDER\n  NEUTROIS\n  TWO_SPIRIT\n  // Self-discovery\n  QUESTIONING\n  GENDER_NONCONFORMING\n  // Fallbacks\n  OTHER\n  PREFER_NOT_TO_SAY\n  // Legacy (backward compat)\n  MALE\n  FEMALE\n}\n\nenum DomSubRole {\n  // Core power dynamics\n  DOMINANT\n  SUBMISSIVE\n  SWITCH\n  // Positional\n  TOP\n  BOTTOM\n  // Specialized dynamics\n  BRAT\n  BRAT_TAMER\n  PRIMAL\n  RIGGER\n  ROPE_BUNNY\n  OWNER\n  PET\n  SADIST\n  MASOCHIST\n  DADDY_MOMMY\n  LITTLE\n  MASTEX\n  // Vanilla & exploring\n  VANILLA\n  EXPLORING\n  PREFER_NOT_TO_SAY\n}\n\nenum KinkExperienceLevel {\n  BEGINNER\n  INTERMEDIATE\n  EXPERIENCED\n  EXPERT\n  PREFER_NOT_TO_SAY\n}\n\nenum RelationshipGoal {\n  // v3 onboarding standard values\n  MONOGAMY // One & Only — committed exclusive connection\n  ETHICAL_NON_MONOGAMY // Open Hearts — multiple connections, honest boundaries\n  POLYAMORY // Many Loves — multiple meaningful relationships\n  CASUAL_DATING // Go With Flow — no labels, see where it goes\n  FRIENDSHIP_FIRST // Friends First — connection before romance\n  KINK_BDSM // Power Play — exploring dynamics & desires\n  // Legacy values (kept for backward compat)\n  LONG_TERM\n  DATING\n  FRIENDSHIP\n  NOT_SURE\n}\n\nenum ProfileStatus {\n  DRAFT // Onboarding in progress\n  PENDING_REVIEW // Submitted, waiting for admin review\n  APPROVED // Ready for matching\n  REJECTED // Needs revision\n  DEACTIVATED // User deactivated\n  BANNED // Admin banned\n}\n\nenum MatchStatus {\n  PENDING // Created, waiting for reactions\n  ACCEPTED // Both accepted\n  REJECTED // One or both rejected\n  EXPIRED // Not acted upon within timeframe\n  CANCELLED // Admin cancelled\n}\n\nenum MatchType {\n  WEEKLY // Regular weekly match\n  BOOSTED // Premium priority match\n  MANUAL // Admin-curated match\n  AI_SUGGESTED // AI recommendation (requires approval)\n}\n\nenum MatchAction {\n  INTERESTED // \"I'd like to connect\"\n  PASS // \"Not for me right now\"\n  MAYBE // \"Tell me more\"\n  BLOCK // \"Don't match me with this person\"\n  SUPER_LIKE // \"Super Like — highlight in recommendations\"\n}\n\nenum MessageType {\n  TEXT\n  IMAGE\n  SYSTEM // Auto-generated messages\n  VOICE // Future: voice notes\n}\n\n// IM Module Message Types\nenum IMMessageType {\n  TEXT\n  IMAGE\n  VOICE\n  FILE\n  SYSTEM\n  CONSENT_REQUEST\n  CONSENT_RESPONSE\n  RULE_UPDATE\n  TYPING\n  READ_RECEIPT\n}\n\nenum ConversationState {\n  ACTIVE\n  PAUSED // one party paused\n  BLOCKED\n  EXPIRED // auto-expired (e.g. Vault expired)\n  ARCHIVED\n}\n\nenum ConsentState {\n  CONSENT_NONE\n  CONSENT_PENDING\n  CONSENT_GRANTED\n  CONSENT_DENIED\n  CONSENT_EXPIRED\n}\n\nenum MediaAccessLevel {\n  L0_TEXT // text only\n  L1_IMAGE // static images\n  L2_VOICE // voice messages\n  L3_VIDEO // video / live calls\n  L4_LOCATION // location sharing\n  L5_CONTACT // contact info\n}\n\nenum RuleEngineResult {\n  PASS\n  SOFT_BLOCK // suggest adjustment, can override\n  HARD_BLOCK // forced block\n  PACE_LIMIT // rate limit\n}\n\nenum EncryptionMode {\n  E2EE // end-to-end encrypted\n  SERVER // server-readable (safety mode)\n  HYBRID // hybrid mode\n}\n\nenum MessageDeliveryStatus {\n  SENDING\n  SENT\n  DELIVERED\n  READ\n  FAILED\n}\n\nenum PresenceStatus {\n  ONLINE\n  AWAY\n  BUSY\n  OFFLINE\n}\n\nenum ConsentRequestType {\n  MEDIA\n  LOCATION\n  CONTACT\n  INTIMATE // intimate content\n}\n\nenum NotificationType {\n  NEW_MATCH\n  MATCH_ACCEPTED\n  MATCH_REJECTED\n  NEW_MESSAGE\n  WEEKLY_DIGEST\n  PROFILE_APPROVED\n  PROFILE_REJECTED\n  SUBSCRIPTION_EXPIRED\n  SYSTEM_ANNOUNCEMENT\n}\n\nenum SubscriptionPlan {\n  FREE\n  LADY_FREE\n  PREMIUM_MONTHLY\n  PREMIUM_YEARLY\n  LIFETIME\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELLED\n  EXPIRED\n  PAST_DUE\n  TRIALING\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCEEDED\n  FAILED\n  REFUNDED\n}\n\n// ═══════════════════════════════════════════════════════════════\n// PRODUCT OPTIMIZATION: Sincerity System & Vault\n// ═══════════════════════════════════════════════════════════════\n\nenum VaultStatus {\n  ACTIVE // 正常进行中\n  EXTENDED // 已延长\n  REVOKED // 被女性终止\n  EXPIRED // 时间到自动关闭\n}\n\nenum SincerityTransactionType {\n  EARN // 赚取\n  SPEND // 消费\n  RECEIVE_GIFT // 收到礼物\n  SEND_GIFT // 送出礼物\n  REFUND // 退款\n}\n\nmodel SincerityWallet {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Balance\n  balance       Int @default(0) // 当前余额\n  totalEarned   Int @default(0) // 累计获得\n  totalSpent    Int @default(0) // 累计消费\n  totalGifted   Int @default(0) // 累计送出礼物\n  totalReceived Int @default(0) // 累计收到礼物\n\n  // Tier System\n  tier         SincerityTier @default(BRONZE)\n  tierProgress Float         @default(0) // 到下一级的进度 0-100\n\n  // Stats\n  lastEarnedAt DateTime?\n  lastSpentAt  DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  transactions SincerityTransaction[]\n\n  @@index([tier])\n  @@index([balance])\n}\n\nmodel SincerityTransaction {\n  id       String          @id @default(cuid())\n  walletId String\n  wallet   SincerityWallet @relation(fields: [walletId], references: [id], onDelete: Cascade)\n\n  // Transaction Details\n  type   SincerityTransactionType\n  amount Int\n\n  // Source/Reason\n  source      String // \"PROFILE_COMPLETE\", \"DAILY_LOGIN\", \"MATCH_ACCEPTED\", \"PITCH_SEND\", etc.\n  description String? // 用户可见的描述\n\n  // Related Entities\n  matchId    String? // 关联的匹配\n  fromUserId String? // 送礼人\n  toUserId   String? // 收礼人\n  message    String? // 附言\n\n  // Metadata\n  metadata String? // JSON for additional data\n\n  createdAt DateTime @default(now())\n\n  @@index([walletId])\n  @@index([type])\n  @@index([createdAt])\n  @@index([source])\n}\n\nenum SincerityTier {\n  BRONZE // 0-499\n  SILVER // 500-1999\n  GOLD // 2000-4999\n  PLATINUM // 5000+\n}\n\n// ═══════════════════════════════════════════════════════════════\n// SAFETY & MODERATION — User Block List\n// ═══════════════════════════════════════════════════════════════\n\nmodel Block {\n  id        String @id @default(cuid())\n  blockerId String // User who blocks\n  blocker   User   @relation(\"BlockerRelations\", fields: [blockerId], references: [id], onDelete: Cascade)\n  blockedId String // User who is blocked\n  blocked   User   @relation(\"BlockedRelations\", fields: [blockedId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  // Prevent duplicate blocks\n  @@unique([blockerId, blockedId], name: \"unique_block_pair\")\n  @@index([blockerId])\n  @@index([blockedId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// SAFETY & MODERATION — User Reports\n// ═══════════════════════════════════════════════════════════════\n\nenum ReportReason {\n  INAPPROPRIATE_CONTENT\n  HARASSMENT\n  FAKE_PROFILE\n  SPAM\n  OFFENSIVE_BEHAVIOR\n  OTHER\n}\n\nenum ReportStatus {\n  PENDING\n  UNDER_REVIEW\n  RESOLVED_NO_ACTION\n  RESOLVED_WARNING\n  RESOLVED_BANNED\n  DISMISSED\n}\n\nmodel UserReport {\n  id String @id @default(cuid())\n\n  // Reporter (who made the report)\n  reporterId String\n  reporter   User   @relation(\"ReportsMade\", fields: [reporterId], references: [id], onDelete: Cascade)\n\n  // Reported user (who was reported)\n  reportedUserId String\n  reportedUser   User   @relation(\"ReportsReceived\", fields: [reportedUserId], references: [id], onDelete: Cascade)\n\n  // Report details\n  reason      ReportReason\n  description String?\n\n  // Context (optional)\n  chatRoomId String?\n  messageId  String?\n\n  // Status tracking\n  status     ReportStatus @default(PENDING)\n  reviewedBy String? // Admin user ID\n  reviewedAt DateTime?\n  adminNotes String?\n\n  // Resolution\n  actionTaken String? // \"WARNING\", \"BAN\", \"NONE\", etc.\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Soft delete (v3.0)\n  deletedAt DateTime?\n\n  @@index([reporterId])\n  @@index([reportedUserId])\n  @@index([status])\n  @@index([createdAt])\n  @@index([status, createdAt])\n  @@index([deletedAt])\n  @@index([reporterId, reportedUserId, createdAt])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// ANALYTICS TRACKING — Event Definition & Aggregation\n// ═══════════════════════════════════════════════════════════════\n\nmodel AnalyticsEventDef {\n  id          String   @id @default(cuid())\n  name        String   @unique // e.g. \"user.registered\"\n  category    String // \"user\"|\"match\"|\"chat\"|\"revenue\"|\"admin\"\n  description String   @default(\"\")\n  properties  String   @default(\"{}\") // JSON Schema\n  isActive    Boolean  @default(true)\n  sampleRate  Float    @default(1.0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\nmodel AnalyticsDailyAgg {\n  id         String   @id @default(cuid())\n  date       DateTime // aggregation date\n  eventName  String // event name\n  metricName String // \"count\"|\"unique_users\"|\"avg_value\"\n  value      Float // metric value\n  dimensions String   @default(\"{}\") // JSON dimensions\n  createdAt  DateTime @default(now())\n\n  @@unique([date, eventName, metricName, dimensions])\n  @@index([date])\n  @@index([date, eventName])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// TENANCY — T01 身份与多租户底座\n//\n// 对齐契约：contracts/schema.sql:4-14 (organizations / memberships / persons)\n// 与 schema.sql:55-59 (audit_events)。\n//\n// 设计约束（来自 MIGRATION_PLAN.md §2）：\n//   1. 加列优先（Additive-first）—— 本文件**全部为新增模型**，不改动既有 39 个模型\n//      的任何列语义，因此可先于任何数据回填独立上线，零停机、零回归。\n//   2. `User` ↔ 契约的 `persons` 同义。为避免全站重命名（P1-6 阶段已清理过一轮\n//      Legacy 命名），保持 `User` 不动，仅在语义层建立映射。\n//   3. 方言无关：本文件不包含任何 `@db.*` 原生类型标注，同一份定义可同时为\n//      libSQL（当前生产）与 PostgreSQL（M6 目标）生成；差异只体现在迁移 SQL。\n//   4. 绝不信任客户端传入的 organizationId —— 解析逻辑见 src/lib/tenancy/。\n// ═══════════════════════════════════════════════════════════════\n\n/// 租户角色。取值与 contracts/schema.sql:12 的 CHECK 约束逐字一致。\nenum MembershipRole {\n  OWNER // 租户所有者：可转让、可删除租户\n  ADMIN // 管理员：可管理成员与全部业务资源\n  OPERATOR // 运营：可创建/执行 Mission 与连接，不可管理成员\n  MEMBER // 成员：仅可操作自己的 Intent / Consent\n}\n\n/// 租户状态。\nenum OrganizationStatus {\n  ACTIVE\n  SUSPENDED // 停用：可读不可写，用于风控与欠费\n}\n\n/// 成员状态。\nenum MembershipStatus {\n  ACTIVE\n  INVITED // 已邀请未接受：不产生任何租户内权限\n  SUSPENDED // 已停用：保留数据，权限立即失效\n}\n\n/// 租户（组织）。对应契约 organizations 表。\nmodel Organization {\n  id        String             @id @default(cuid())\n  name      String\n  /// 对外可读标识，用于 URL 与分享页；唯一。\n  slug      String             @unique\n  status    OrganizationStatus @default(ACTIVE)\n  createdAt DateTime           @default(now())\n  updatedAt DateTime           @updatedAt\n\n  memberships Membership[]\n  auditEvents TenantAuditEvent[]\n\n  // ── T02 Connection OS 反向关系（connection.prisma）──\n  missions              Mission[]\n  missionParticipations MissionParticipation[]\n  idempotencyRecords    IdempotencyRecord[]\n\n  @@index([status])\n}\n\n/// 成员关系（用户 × 租户）。对应契约 memberships 表。\n/// 契约用复合主键 (organization_id, person_id)；Prisma 用代理主键 + 唯一约束表达，\n/// 语义等价且便于后续扩展（如软删除、审计字段）。\nmodel Membership {\n  id             String           @id @default(cuid())\n  organizationId String\n  userId         String\n  role           MembershipRole   @default(MEMBER)\n  status         MembershipStatus @default(ACTIVE)\n  createdAt      DateTime         @default(now())\n  updatedAt      DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  user         User         @relation(\"UserMemberships\", fields: [userId], references: [id], onDelete: Cascade)\n\n  /// 同一租户内同一用户只能有一条成员关系。\n  @@unique([organizationId, userId])\n  /// 反查「我属于哪些租户」是每次会话建立时的热路径。\n  @@index([userId, status])\n  @@index([organizationId, role])\n}\n\n/// 租户级审计事件。对应契约 audit_events 表。\n///\n/// 与既有 `AuditLog`（core.prisma 哈希链审计）**并存**，分工如下：\n///   - `AuditLog`      ：既有产品行为的不可抵赖链（保留 prevHash/entryHash），不动。\n///   - `TenantAuditEvent`：闭环的**安全事件流**（租户/成员/授权/越权尝试），\n///                        可写 `safeMetadata`（脱敏，禁止放 PII 明文）。\n/// 收敛计划见 REUSE_MATRIX.md B5（M5 之后）。\nmodel TenantAuditEvent {\n  id             String   @id @default(cuid())\n  organizationId String\n  /// 触发者；系统触发时为 null（例如定时任务、迁移）。\n  actorId        String?\n  /// 事件类型，命名规范：`<domain>.<action>`，如 `membership.role_changed`。\n  eventType      String\n  /// 资源类型，如 `membership` / `mission` / `proposal`。\n  resourceType   String\n  resourceId     String?\n  /// 脱敏元数据（JSON 文本）。**禁止**写入密码、令牌、完整邮箱等 PII。\n  safeMetadata   String?\n  createdAt      DateTime @default(now())\n\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  @@index([organizationId, createdAt])\n  @@index([organizationId, eventType])\n  @@index([resourceType, resourceId])\n}\n"
}

